                <select x-model="row.product_plan_category_id" class="rounded-xl border-slate-200"><option value="">Global category</option><template x-for="category in categories" :key="category.id"><option :value="category.id" x-text="categoryLabel(category)"></option></template></select>
                <input x-model="row.route.provider_plan_id" placeholder="Provider external plan ID" class="rounded-xl border-slate-200">
                <select x-model="row.route.parent_provider_connection_id" class="rounded-xl border-slate-200"><option value="">Approved provider</option><template x-for="connection in connections" :key="connection.id"><option :value="connection.id" x-text="connection.name"></option></template></select>
                <input x-model="row.api_id" placeholder="Internal/API reference" class="rounded-xl border-slate-200">
                <input x-model="row.cost_price" type="number" min="0" step="0.01" placeholder="Provider cost" class="rounded-xl border-slate-200">
                <input x-model="row.data_size_in_mb" type="number" min="0" step="0.01" placeholder="Data size MB" class="rounded-xl border-slate-200">
                <input x-model="row.validity_in_days" type="number" min="0" placeholder="Validity days" class="rounded-xl border-slate-200">
            </div><div class="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3"><template x-for="price in row.prices" :key="price.parent_reseller_level_id"><label class="rounded-xl bg-slate-50 p-3 text-xs font-semibold"><span x-text="levelName(price.parent_reseller_level_id)"></span><input x-model="price.selling_price" type="number" min="0" step="0.01" placeholder="Selling price" class="mt-2 w-full rounded-lg border-slate-200 font-normal"></label></template></div><div class="mt-4 flex flex-wrap gap-4 text-xs"><label><input x-model="row.visibility" type="checkbox"> Active</label><label><input x-model="row.affiliate_visibility" type="checkbox"> Affiliates</label><label><input x-model="row.public_visibility" type="checkbox"> Public</label></div></article></template>
            <div class="flex flex-wrap justify-between gap-3"><button type="button" @click="addBulkRow" class="rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-semibold">Add another row</button><button type="button" @click="createBulk" :disabled="saving" class="rounded-xl bg-blue-600 px-5 py-3 font-semibold text-white disabled:opacity-50" x-text="saving?'Creating batch…':`Create ${bulkPlans.length} plans`"></button></div>
        </div>
    </section>

    <section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
        <div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-5"><div><h2 class="font-semibold">Parent product plans</h2><p class="text-sm text-slate-500" x-text="paginationText"></p></div><input x-model="search" type="search" placeholder="Search this page" class="w-full rounded-xl border-slate-200 sm:w-72"></div>
        <div x-show="loading" class="p-8 text-center text-sm text-slate-500">Loading product plans…</div>
        <div x-show="!loading" class="overflow-x-auto"><table class="w-full min-w-[1250px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-4">Plan</th><th class="p-4">Global category</th><th class="p-4">Provider cost</th><th class="p-4">Primary route</th><th class="p-4">Validity</th><th class="p-4">Availability</th><th class="p-4"></th></tr></thead><tbody class="divide-y"><template x-for="plan in filteredPlans" :key="plan.id"><tr>
            <td class="p-4"><input x-model="plan.product_plan_name" class="w-56 rounded-lg border-slate-200"><p class="mt-1 text-xs text-slate-400" x-text="plan.api_id||''"></p></td>
            <td class="p-4"><select x-model="plan.product_plan_category_id" class="w-64 rounded-lg border-slate-200"><template x-for="category in categories" :key="category.id"><option :value="category.id" x-text="categoryLabel(category)"></option></template></select></td>
            <td class="p-4"><input x-model="plan.cost_price" type="number" min="0" step="0.01" class="w-28 rounded-lg border-slate-200"></td>
            <td class="p-4"><p class="font-medium" x-text="plan.provider_routes?.[0]?.provider_plan_id||'Draft — no route'"></p><p class="text-xs text-slate-400" x-text="plan.provider_routes?.[0]?.parent_provider_connection?.name||''"></p></td>
            <td class="p-4"><span x-text="plan.validity_in_days?`${plan.validity_in_days} days`:'—'"></span></td>
            <td class="p-4"><div class="space-y-1 text-xs"><label class="block"><input x-model="plan.visibility" true-value="1" false-value="0" type="checkbox"> Active</label><label class="block"><input x-model="plan.affiliate_visibility" true-value="1" false-value="0" type="checkbox"> Affiliates</label><label class="block"><input x-model="plan.public_visibility" true-value="1" false-value="0" type="checkbox"> Public</label></div></td>
            <td class="p-4"><button @click="save(plan)" :disabled="saving" class="rounded-lg bg-slate-950 px-3 py-2 text-xs font-semibold text-white disabled:opacity-50">Save</button></td>
        </tr></template></tbody></table></div>
        <div class="flex items-center justify-between border-t border-slate-100 p-4"><button @click="load(pagination.current_page-1)" :disabled="loading||pagination.current_page<=1" class="rounded-lg border border-slate-200 px-3 py-2 text-sm font-semibold disabled:opacity-40">Previous page</button><span class="text-sm text-slate-500" x-text="`Page ${pagination.current_page} of ${pagination.last_page}`"></span><button @click="load(pagination.current_page+1)" :disabled="loading||pagination.current_page>=pagination.last_page" class="rounded-lg border border-slate-200 px-3 py-2 text-sm font-semibold disabled:opacity-40">Next page</button></div>
    </section>
</div>
