@push('scripts')
<script>
document.addEventListener('alpine:init',()=>Alpine.data('parentPlans',()=>({
    plans:[],categories:[],connections:[],levels:[],bulkPlans:[],form:{},mode:'single',loading:false,saving:false,search:'',notice:'',error:'',pagination:{current_page:1,last_page:1,total:0,from:0,to:0},
    urls:{data:@js(route('parent-admin.product-plans.data')),store:@js(route('parent-admin.product-plans.store')),bulk:@js(route('parent-admin.product-plans.bulk-store')),base:@js(url('/parent-admin/product-plans'))},
    get filteredPlans(){const q=this.search.toLowerCase();return this.plans.filter(p=>`${p.product_plan_name} ${p.api_id||''} ${p.product_plan_category?.product_plan_category_name||''}`.toLowerCase().includes(q))},
    get paginationText(){return this.pagination.total?`Showing ${this.pagination.from}–${this.pagination.to} of ${this.pagination.total} plans`:'No plans found'},
    categoryLabel(c){return `${c.product_plan_category_name} · ${c.network?.network_name||c.product?.product_name||'General'}`},
    levelName(id){return this.levels.find(level=>String(level.id)===String(id))?.name||'Reseller level'},
    blankPlan(){const active=this.connections.length>0&&this.levels.length>0;return {client_id:crypto.randomUUID(),product_plan_name:'',product_plan_category_id:'',api_id:'',admin_cost_price:'',cost_price:'',data_size_in_mb:'',validity_in_days:'',profit_category:'flat',commission_feature:true,upline_commission_option:'flat',upline_flat_commission:0,upline_percentage_commission:0,upline_commission_cap:1000,visibility:active,affiliate_visibility:active,public_visibility:active,route:{parent_provider_connection_id:this.connections[0]?.id||'',provider_plan_id:''},prices:this.levels.map(level=>({parent_reseller_level_id:level.id,selling_price:'',max_profit:''}))}},
    clean(plan){const copy=structuredClone(plan);delete copy.client_id;['api_id','admin_cost_price','data_size_in_mb','validity_in_days'].forEach(key=>{if(copy[key]==='')copy[key]=null});copy.prices.forEach(price=>{if(price.max_profit==='')price.max_profit=null});if(!copy.route.parent_provider_connection_id&&!copy.route.provider_plan_id)copy.route=null;return copy},
    async load(page=1){this.loading=true;this.error='';try{const {data}=await axios.get(this.urls.data,{params:{page}});this.plans=data.plans.data;this.categories=data.categories;this.connections=data.connections;this.levels=data.levels;this.pagination={current_page:data.plans.current_page,last_page:data.plans.last_page,total:data.plans.total,from:data.plans.from||0,to:data.plans.to||0};if(!this.form.product_plan_name)this.form=this.blankPlan();if(this.bulkPlans.length===0)this.bulkPlans=[this.blankPlan()]}catch(e){this.fail(e)}finally{this.loading=false}},
    openBulk(){this.mode='bulk';if(this.bulkPlans.length===0)this.bulkPlans=[this.blankPlan()]},addBulkRow(){this.bulkPlans.push(this.blankPlan())},removeBulkRow(index){this.bulkPlans.splice(index,1)},
    async createPlan(){this.saving=true;this.error='';try{const {data}=await axios.post(this.urls.store,this.clean(this.form));this.form=this.blankPlan();await this.load(1);this.show(data.message)}catch(e){this.fail(e)}finally{this.saving=false}},
    async createBulk(){this.saving=true;this.error='';try{const {data}=await axios.post(this.urls.bulk,{plans:this.bulkPlans.map(plan=>this.clean(plan))});this.bulkPlans=[this.blankPlan()];await this.load(1);this.show(data.message)}catch(e){this.fail(e)}finally{this.saving=false}},
    async save(plan){this.saving=true;this.error='';try{const {data}=await axios.patch(`${this.urls.base}/${plan.id}`,plan);Object.assign(plan,data.plan);this.show(data.message)}catch(e){this.fail(e)}finally{this.saving=false}},
    show(message){this.notice=message;setTimeout(()=>this.notice='',3500)},fail(e){this.error=Object.values(e.response?.data?.errors||{}).flat()[0]||e.response?.data?.message||'Unable to complete this action.'}
})))
</script>
@endpush
